CREATE FUNCTION public.flat_bill_position(_flat uuid,_month date,_asof date DEFAULT (now() AT TIME ZONE 'Asia/Kolkata')::date) RETURNS TABLE(charged numeric,paid numeric,billed numeric,previous_due numeric,current_due numeric,credit numeric,account_status text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE startdate date; m date; charge numeric; remaining numeric; partial_bill boolean:=false; BEGIN
 IF auth.uid() IS NOT NULL AND NOT public.has_permission('finance.read') AND NOT EXISTS(SELECT 1 FROM public.flats WHERE id=_flat AND resident_user_id=auth.uid()) THEN RAISE EXCEPTION 'Flat access required' USING ERRCODE='42501'; END IF;
 SELECT billing_start INTO startdate FROM public.flats WHERE id=_flat;
 IF NOT FOUND THEN RETURN; END IF;
 charged:=public.billed_total(_flat,startdate,(date_trunc('month',_month)+interval '1 month')::date);
 SELECT coalesce(sum(amount),0) INTO paid FROM public.payments WHERE flat_id=_flat AND status='confirmed' AND paid_on<(date_trunc('month',_month)+interval '1 month')::date AND paid_on<=least(_asof,(now() AT TIME ZONE 'Asia/Kolkata')::date);
 billed:=CASE WHEN date_trunc('month',startdate)<=date_trunc('month',_month) THEN public.bill_amount(_flat,_month) ELSE 0 END;
 previous_due:=greatest(charged-billed-paid,0); current_due:=least(greatest(charged-paid,0),billed); credit:=greatest(paid-charged,0);
 remaining:=paid;
 FOR m IN SELECT generate_series(date_trunc('month',startdate),date_trunc('month',_month),interval '1 month')::date LOOP charge:=public.bill_amount(_flat,m); IF remaining>0 AND remaining<charge THEN partial_bill:=true; END IF; remaining:=greatest(remaining-charge,0); END LOOP;
 account_status:=CASE WHEN charged<=paid THEN 'paid' WHEN partial_bill THEN 'partial' ELSE 'outstanding' END;
 RETURN NEXT;
END $$;
REVOKE ALL ON FUNCTION public.flat_bill_position(uuid,date,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.flat_bill_position(uuid,date,date) TO authenticated,service_role;
CREATE OR REPLACE VIEW public.flat_accounts WITH(security_invoker=true) AS SELECT f.id,f.flat_number,f.resident_name,f.mobile,f.resident_user_id,f.billing_start,greatest((extract(year from (now() AT TIME ZONE 'Asia/Kolkata')::date)-extract(year from f.billing_start))*12+extract(month from (now() AT TIME ZONE 'Asia/Kolkata')::date)-extract(month from f.billing_start)+1,0)::integer AS months_billed,s.paid AS total_paid,s.charged AS total_charged,s.previous_due+s.current_due AS outstanding,s.billed AS current_month_amount,s.previous_due AS previous_outstanding,s.account_status AS status,s.current_due AS current_outstanding,s.credit AS advance_credit FROM public.flats f CROSS JOIN LATERAL public.flat_bill_position(f.id,(now() AT TIME ZONE 'Asia/Kolkata')::date) s;
CREATE OR REPLACE VIEW public.finance_accounts WITH(security_barrier=true) AS SELECT f.id,f.flat_number,f.resident_name,f.billing_start,s.previous_due+s.current_due AS outstanding,s.billed AS current_month_amount,s.account_status AS status,s.current_due AS current_outstanding,s.credit AS advance_credit FROM public.flats f CROSS JOIN LATERAL public.flat_bill_position(f.id,(now() AT TIME ZONE 'Asia/Kolkata')::date) s WHERE public.has_permission('finance.read');
CREATE OR REPLACE FUNCTION public.financial_report_snapshot(_start date,_end date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; opening_due numeric; billed numeric; closing_due numeric; opening_credit numeric; closing_credit numeric; fy integer; fydate date; opening numeric; today date:=(now() AT TIME ZONE 'Asia/Kolkata')::date; BEGIN
 result:=public.financial_report_snapshot_legacy(_start,_end);
 WITH calc AS (SELECT public.billed_total(f.id,f.billing_start,_start) before_bill,public.billed_total(f.id,greatest(date_trunc('month',billing_start)::date,_start),_end) period_bill,coalesce((SELECT sum(amount) FROM public.payments WHERE flat_id=f.id AND status='confirmed' AND paid_on<_start AND paid_on<=today),0) before_paid,coalesce((SELECT sum(amount) FROM public.payments WHERE flat_id=f.id AND status='confirmed' AND paid_on<_end AND paid_on<=today),0) end_paid FROM public.flats f)
 SELECT coalesce(sum(greatest(before_bill-before_paid,0)),0),coalesce(sum(period_bill),0),coalesce(sum(greatest(before_bill+period_bill-end_paid,0)),0),coalesce(sum(greatest(before_paid-before_bill,0)),0),coalesce(sum(greatest(end_paid-before_bill-period_bill,0)),0) INTO opening_due,billed,closing_due,opening_credit,closing_credit FROM calc;
 fy:=extract(year from _start)::int-CASE WHEN extract(month from _start)<(public.maintenance_rate(_start)).fy_start_month THEN 1 ELSE 0 END; fydate:=make_date(fy,(public.maintenance_rate(_start)).fy_start_month,1);
 SELECT coalesce((SELECT opening_balance FROM public.fund_years WHERE fy_start=fy),0)+coalesce((SELECT sum(amount) FROM public.payments WHERE status='confirmed' AND paid_on>=fydate AND paid_on<_start AND paid_on<=today),0)-coalesce((SELECT sum(amount) FROM public.expenses WHERE coalesce(expense_month,to_char(expense_date,'YYYY-MM'))>=to_char(fydate,'YYYY-MM') AND coalesce(expense_month,to_char(expense_date,'YYYY-MM'))<to_char(_start,'YYYY-MM')),0) INTO opening;
 RETURN result||jsonb_build_object('openingOutstanding',opening_due,'maintenanceBilled',billed,'outstandingDues',closing_due,'openingAdvanceCredit',opening_credit,'closingAdvanceCredit',closing_credit,'openingBalance',opening,'closingBalance',opening+(result->>'totalIncome')::numeric-(result->>'totalExpenses')::numeric,'openingBalanceRecorded',EXISTS(SELECT 1 FROM public.fund_years WHERE fy_start=fy),'basis','Confirmed receipts use actual payment dates through the society date. Expenses use recorded accounting months, falling back to payment month. Bills use immutable monthly charges and approved effective-month rates. Payments clear oldest dues within each flat; advance credit stays with that flat. Opening dues minus opening credit plus bills minus receipts equals closing dues minus closing credit. Existing report snapshots are unchanged.');
END $$;